{
  "avaliacoes": [
    {
      "id": "E68ff9b835100fc73",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O guia trata a segurança funcional como parte de um conjunto de medidas para minimizar risco e prevenir eventos perigosos, e remete a temas de projeto e operação como HAZOP, limites operacionais seguros, tempo de segurança de processo, gestão de alarmes, overrides/inibits e outras medidas de prevenção.",
          "trechos": [
            "E68ff9b835100fc73:0:699",
            "E68ff9b835100fc73:699:1396"
          ],
          "condicoes": [
            "aplicável ao contexto de inspeção de segurança funcional em instalações offshore",
            "relaciona-se a funções instrumentadas e medidas de prevenção de eventos perigosos"
          ],
          "limites": [
            "a fonte não detalha procedimentos de patching, hardening, gestão de vulnerabilidades ou critérios de indisponibilidade cibernética",
            "o enquadramento é de guia de inspeção e referência a norma BS EN 61511, não requisito brasileiro automático"
          ]
        },
        {
          "proposicao": "Na avaliação de componentes de função instrumentada que não estejam operando como projetado, o guia indica recorrer a orientação de avaliação de risco operacional para gestão do risco em condições anormais.",
          "trechos": [
            "E68ff9b835100fc73:1396:2085"
          ],
          "condicoes": [
            "quando componentes de SIF não estiverem funcionando conforme o projeto",
            "em cenários de condição anormal"
          ],
          "limites": [
            "a fonte não fornece método quantitativo de avaliação de indisponibilidade nem critérios de aceitação",
            "não descreve integração detalhada com resposta a incidentes cibernéticos"
          ]
        },
        {
          "proposicao": "O guia aponta que a inspeção de cibersegurança de IACS deve ser tratada por guia específico e que apoio especializado pode ser necessário para esclarecer demonstrações de conformidade.",
          "trechos": [
            "E68ff9b835100fc73:699:1396",
            "E68ff9b835100fc73:1396:2085"
          ],
          "condicoes": [
            "quando a inspeção envolver risco cibernético em sistemas de automação e controle",
            "quando houver necessidade de avaliar demonstração de conformidade ou suporte técnico especializado"
          ],
          "limites": [
            "a fonte apenas referencia o guia específico de cibersegurança, sem descrever controles técnicos",
            "não apresenta critérios de seleção de contramedidas ou compatibilidade entre sistemas"
          ]
        }
      ]
    },
    {
      "id": "E2d81a6a16a58e987",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O guia de inspeção de cibersegurança para IACS adota abordagem proporcional e direcionada, com categorias distintas para inspeções iniciais e subsequentes em instalações NIS e não NIS.",
          "trechos": [
            "E2d81a6a16a58e987:0:698",
            "E2d81a6a16a58e987:698:1391",
            "E2d81a6a16a58e987:1391:2091"
          ],
          "condicoes": [
            "aplicável ao contexto regulatório do UKCS e das categorias de inspeção definidas pelo guia",
            "usado para planejar inspeções de cibersegurança em IACS"
          ],
          "limites": [
            "a categorização é específica do arranjo regulatório britânico e não deve ser tratada como requisito brasileiro",
            "a fonte não detalha medidas técnicas de hardening, patching ou segmentação de rede"
          ]
        },
        {
          "proposicao": "O objetivo da inspeção é verificar a adequação do sistema de gestão de cibersegurança de IACS, incluindo gestão de competências e efetividade das contramedidas de cibersegurança.",
          "trechos": [
            "E2d81a6a16a58e987:1391:2091",
            "E2d81a6a16a58e987:2091:2518"
          ],
          "condicoes": [
            "quando a instalação se enquadra no escopo do guia para locais com potencial de acidente maior ou serviços essenciais",
            "na avaliação de arranjos de gestão e contramedidas"
          ],
          "limites": [
            "a fonte não define métricas operacionais de efetividade nem método de teste sem impacto à disponibilidade",
            "não especifica controles concretos por ativo ou sistema"
          ]
        }
      ]
    },
    {
      "id": "Ea3d79d3ac748d62d",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "No escopo do guia, IACS abrange sistemas básicos de controle de processo, funções de camada independente de proteção, sistemas de segurança, sistemas elétricos de controle/aquisição de dados e sistemas de informação e de negócios conectados pela infraestrutura de rede do IACS.",
          "trechos": [
            "Ea3d79d3ac748d62d:0:700",
            "Ea3d79d3ac748d62d:700:1390"
          ],
          "condicoes": [
            "aplicável à definição de escopo usada pelo guia de inspeção",
            "considera conectividade via infraestrutura de rede do IACS"
          ],
          "limites": [
            "a enumeração define escopo, mas não estabelece por si só critérios de segregação, menor privilégio ou compatibilidade entre domínios",
            "o enquadramento regulatório é estrangeiro"
          ]
        },
        {
          "proposicao": "Para ambiente offshore, o guia indica que o escopo de IACS pode incluir também sistemas marítimos, de perfuração e de monitoramento de movimento de helicópteros.",
          "trechos": [
            "Ea3d79d3ac748d62d:700:1390"
          ],
          "condicoes": [
            "quando tais sistemas estiverem presentes e integrados ao ambiente IACS offshore"
          ],
          "limites": [
            "a fonte usa 'pode incluir', portanto não confirma presença universal desses sistemas em toda instalação offshore ou FPSO",
            "não detalha consequências operacionais específicas por tipo de sistema"
          ]
        },
        {
          "proposicao": "Para instalações reguladas por NIS, a autoavaliação baseada no CAF do NCSC e o plano de melhoria decorrente são usados como ponto de partida para inspeções amostrais, com indicadores estruturados de higiene cibernética e análise de lacunas frente ao perfil-alvo.",
          "trechos": [
            "Ea3d79d3ac748d62d:1390:2090",
            "Ea3d79d3ac748d62d:2090:2378"
          ],
          "condicoes": [
            "quando a instalação estiver no escopo NIS do arranjo regulatório citado",
            "após realização de autoavaliação e elaboração de plano de melhoria"
          ],
          "limites": [
            "os indicadores e o uso do CAF pertencem ao contexto regulatório do Reino Unido",
            "a fonte não informa como converter resultados da autoavaliação em priorização de patches, hardening ou gestão de legados"
          ]
        }
      ]
    },
    {
      "id": "Ee508666b790e7ceb",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "A fonte relata uma série de falhas em UPS industriais associadas à falta de manutenção, com perda significativa de energia para sistemas de controle industrial, sistemas de shutdown de emergência e sistemas de mitigação de emergência.",
          "trechos": [
            "Ee508666b790e7ceb:0:699"
          ],
          "condicoes": [
            "no contexto dos incidentes observados pela autoridade emissora",
            "quando a confiabilidade do UPS é degradada por falhas e falta de manutenção"
          ],
          "limites": [
            "a fonte descreve incidentes e alerta de segurança, não um estudo estatístico generalizável para todas as instalações",
            "não distingue impactos por arquitetura elétrica, regime de redundância ou tipo de ativo"
          ]
        },
        {
          "proposicao": "Em um dos incidentes, a falha de componentes do UPS levou a shutdown da instalação, acionamento do gerador de emergência, disparo de disjuntor de shunt e ocorrência de fumaça e arco elétrico na seção inversora, exigindo isolamento e bloqueio das fontes de energia antes da colocação em bypass seguro.",
          "trechos": [
            "Ee508666b790e7ceb:0:699",
            "Ee508666b790e7ceb:699:1396",
            "Ee508666b790e7ceb:1396:2096"
          ],
          "condicoes": [
            "no incidente específico descrito",
            "após falha de componentes do UPS e problemas adicionais no circuito de potência"
          ],
          "limites": [
            "o relato não informa causa raiz completa, tempo de restauração nem frequência de ocorrência",
            "não permite inferir procedimento universal de resposta para qualquer topologia de UPS"
          ]
        },
        {
          "proposicao": "Em outro incidente durante atividade de teste, a ativação de sistema de segurança de emergência provocou perda de geração e shutdown, seguido de deluge total e alarme de abandono; nesse cenário, o gerador de emergência falhou em partir e o UPS não forneceu a alimentação de backup esperada.",
          "trechos": [
            "Ee508666b790e7ceb:1396:2096",
            "Ee508666b790e7ceb:2096:2360"
          ],
          "condicoes": [
            "durante atividade de teste em instalação offshore",
            "após ativação de sistema de segurança de emergência e perda de geração"
          ],
          "limites": [
            "a fonte não informa o desenho de teste, salvaguardas prévias nem avaliação formal de indisponibilidade antes do teste",
            "o caso evidencia consequência operacional, mas não trata de vulnerabilidade cibernética, patching ou hardening"
          ]
        }
      ]
    },
    {
      "id": "E55b8a6205c6a682e",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte descreve que aplicações de SCADA para gestão de alarmes, historiadores de séries temporais e HMIs com desenho voltado à consciência situacional são usadas para compreender e otimizar múltiplos eventos produzidos por controladores em campo.",
          "trechos": [
            "E55b8a6205c6a682e:0:696"
          ],
          "condicoes": [
            "quando houver múltiplos controladores em campo e necessidade de interpretação de eventos no nível supervisório"
          ],
          "limites": [
            "a fonte não descreve requisitos de segurança para essas aplicações nem controles de hardening ou patching",
            "por ser trecho de corpus concatenado sem fronteira documental clara, o contexto e a autoria são indeterminados"
          ]
        },
        {
          "proposicao": "A diversidade de modelos de dados de controladores de diferentes fornecedores é apontada como desafio, pois dificulta convenções de nomenclatura, padrões de HMI e a comparação entre ativos sem retrabalho de dados.",
          "trechos": [
            "E55b8a6205c6a682e:0:696"
          ],
          "condicoes": [
            "quando coexistem controladores de múltiplos fornecedores ou modelos de dados customizados"
          ],
          "limites": [
            "a fonte trata de interoperabilidade e padronização de dados, não de vulnerabilidades de software específicas",
            "não apresenta critério operacional para seleção entre padronização no controlador, SCADA ou outro nível"
          ]
        },
        {
          "proposicao": "Como as capacidades de padronização são descritas como limitadas na camada de controle, a fonte indica o SCADA como nível mais próximo da origem dos dados em que essa padronização pode ser realizada para viabilizar análises.",
          "trechos": [
            "E55b8a6205c6a682e:696:1394"
          ],
          "condicoes": [
            "quando a padronização na camada de controle é limitada",
            "quando se busca reutilização analítica dos dados"
          ],
          "limites": [
            "a fonte não discute impactos dessa escolha sobre disponibilidade, latência, segurança ou compatibilidade com sistemas legados",
            "não oferece método de implementação ou validação"
          ]
        }
      ]
    },
    {
      "id": "E2b2a291ed253835d",
